91: // execute lists the managed resources for the selected etcd resources based on the filter.
92: func (l *listResourcesCmdCtx) execute(ctx context.Context) error {
93: 	if l.AllNamespaces {
94: 		l.Logger.Info(l.IOStreams.Out, "Listing all Managed resources for Etcds across all namespaces")
95: 	} else {
96: 		l.Logger.Info(l.IOStreams.Out, "Listing Managed resources for selected Etcds")
97: 	}
98: 	out := l.Logger
99: 
100: 	etcdClient := l.EtcdClient
101: 	genClient := l.GenericClient
102: 
103: 	tokens := parseFilter(l.Filter)
104: 	if len(tokens) == 0 || (len(tokens) == 1 && tokens[0] == "all") {
105: 		tokens = defaultResourceTokens()
106: 	}
107: 	resolver := newRESTMapperResolver(genClient.RESTMapper())
108: 	metas, err := resolver.resolve(tokens)
109: 	if err != nil {
110: 		return err
111: 	}
112: 
113: 	// Identify etcds to operate on
114: 	etcdList, err := cmdutils.GetEtcdList(ctx, etcdClient, l.etcdRefList, l.AllNamespaces, l.GetNamespace(), l.LabelSelector)
115: 	if err != nil {
116: 		return err
117: 	}
118: 	if len(etcdList.Items) == 0 {
119: 		if !l.AllNamespaces {
120: 			return fmt.Errorf("no Etcd resources found in namespace %q", l.GetNamespace())
121: 		}
122: 		out.Info(l.IOStreams.Out, "No Etcd resources found across all namespaces")
123: 		return nil
124: 	}
125: 
126: 	result := Result{
127: 		Etcds: make([]EtcdResourceResult, 0, len(etcdList.Items)),
128: 		Kind:  "EtcdResourceList",
129: 	}
130: 	for _, etcd := range etcdList.Items {
131: 		etcdResult := EtcdResourceResult{
132: 			Etcd:  EtcdRef{Name: etcd.Name, Namespace: etcd.Namespace},
133: 			Items: make([]ResourceListPerKey, 0),
134: 		}
135: 
136: 		labelSelector := fmt.Sprintf("app.kubernetes.io/part-of=%s", etcd.Name)
137: 		for _, resMeta := range metas {
138: 			resourceNamespace := ""
139: 			if resMeta.Namespaced {
140: 				resourceNamespace = etcd.Namespace
141: 			}
142: 			resourceList, err := genClient.Dynamic().Resource(resMeta.GVR).Namespace(resourceNamespace).List(ctx, metav1.ListOptions{LabelSelector: labelSelector})
143: 			if err != nil {
144: 				out.Warning(l.IOStreams.Out, "Failed to list ", resMeta.GVR.Resource, " for etcd ", etcd.Name, ": ", err.Error())
145: 				continue
146: 			}
147: 			if len(resourceList.Items) == 0 {
148: 				continue
149: 			}
150: 			resourceKey := ResourceKey{Group: resMeta.GVR.Group, Version: resMeta.GVR.Version, Resource: resMeta.GVR.Resource, Kind: resMeta.Kind}
151: 			for _, item := range resourceList.Items {
152: 				found := false
153: 				for idx, resourceListPerKey := range etcdResult.Items {
154: 					if resourceListPerKey.Key == resourceKey {
155: 						etcdResult.Items[idx].Resources = append(etcdResult.Items[idx].Resources, toResourceRef(&item))
156: 						found = true
157: 						break
158: 					}
159: 				}
160: 				if !found {
161: 					etcdResult.Items = append(etcdResult.Items, ResourceListPerKey{
162: 						Key:       resourceKey,
163: 						Resources: []ResourceRef{toResourceRef(&item)},
164: 					})
165: 				}
166: 			}
167: 		}
168: 		// Sort within each resource kind by namespace/name for determinism
169: 		for kindIdx := range etcdResult.Items {
170: 			sort.Slice(etcdResult.Items[kindIdx].Resources, func(i, j int) bool {
171: 				resourceA, resourceB := etcdResult.Items[kindIdx].Resources[i], etcdResult.Items[kindIdx].Resources[j]
172: 				if resourceA.Namespace == resourceB.Namespace {
173: 					return resourceA.Name < resourceB.Name
174: 				}
175: 				return resourceA.Namespace < resourceB.Namespace
176: 			})
177: 		}
178: 		result.Etcds = append(result.Etcds, etcdResult)
179: 	}
180: 
181: 	// Sort etcds by namespace/name
182: 	sort.Slice(result.Etcds, func(i, j int) bool {
183: 		if result.Etcds[i].Etcd.Namespace == result.Etcds[j].Etcd.Namespace {
184: 			return result.Etcds[i].Etcd.Name < result.Etcds[j].Etcd.Name
185: 		}
186: 		return result.Etcds[i].Etcd.Namespace < result.Etcds[j].Etcd.Namespace
187: 	})
188: 	if l.Printer != nil {
189: 		var outputData []byte
190: 		outputData, err = l.Printer.Print(result)
191: 		if err != nil {
192: 			return fmt.Errorf("failed to marshal result to desired format: %w", err)
193: 		}
194: 		fmt.Fprintf(l.IOStreams.Out, "%s\n", string(outputData))
195: 		return nil
196: 	}
197: 	l.renderListResources(out, result.Etcds)
198: 	return nil
199: }
