201: // parseFilter splits and normalizes the filter string
202: func parseFilter(filter string) []string {
203: 	if strings.TrimSpace(filter) == "" {
204: 		return nil
205: 	}
206: 	parts := strings.Split(filter, ",")
207: 	out := make([]string, 0, len(parts))
208: 	seen := map[string]struct{}{}
209: 	for _, p := range parts {
210: 		t := strings.ToLower(strings.TrimSpace(p))
211: 		if t == "" {
212: 			continue
213: 		}
214: 		if _, ok := seen[t]; ok {
215: 			continue
216: 		}
217: 		seen[t] = struct{}{}
218: 		out = append(out, t)
219: 	}
220: 	return out
221: }
222: 
223: // defaultResourceTokens returns the curated default set for "all"
224: func defaultResourceTokens() []string {
225: 	return []string{"po", "sts", "svc", "cm", "secret", "pvc", "lease", "pdb", "role", "rolebinding", "sa"}
226: }
227: 
228: func toResourceRef(u *unstructured.Unstructured) ResourceRef {
229: 	age := time.Since(u.GetCreationTimestamp().Time)
230: 	return ResourceRef{
231: 		Namespace: u.GetNamespace(),
232: 		Name:      u.GetName(),
233: 		Age:       age,
234: 	}
235: }
236: 
237: // renderListResources prints results in a grouped, neat format using the Logger.
238: func (l *listResourcesCmdCtx) renderListResources(log log.Logger, results []EtcdResourceResult) {
239: 	for _, etcdResourceResult := range results {
240: 		log.RawHeader(l.IOStreams.Out, fmt.Sprintf("Etcd [%s/%s]", etcdResourceResult.Etcd.Namespace, etcdResourceResult.Etcd.Name))
241: 		if len(etcdResourceResult.Items) == 0 {
242: 			log.Info(l.IOStreams.Out, "No resources found for selected filters")
243: 			continue
244: 		}
245: 
246: 		keyList := etcdResourceResult.Items
247: 		sort.Slice(keyList, func(i, j int) bool {
248: 			if keyList[i].Key.Kind == keyList[j].Key.Kind {
249: 				return len(keyList[i].Key.Resource) < len(keyList[j].Key.Resource)
250: 			}
251: 			return len(keyList[i].Key.Kind) < len(keyList[j].Key.Kind)
252: 		})
253: 		table := SetupListResourcesTable(keyList)
254: 		if _, err := fmt.Fprintln(l.IOStreams.Out, table); err != nil {
255: 			log.Warning(l.IOStreams.ErrOut, "Failed writing resources table: ", err.Error())
256: 		}
257: 	}
258: }

