93: // execute lists the managed resources for the selected etcd resources based on the filter.
94: func (l *listResourcesCmdCtx) execute(ctx context.Context) error {
95: 	if l.AllNamespaces {
96: 		l.Logger.Info(l.IOStreams.Out, "Listing all Managed resources for Etcds across all namespaces")
97: 	} else {
98: 		l.Logger.Info(l.IOStreams.Out, "Listing Managed resources for selected Etcds")
99: 	}
100: 	out := l.Logger
101: 
102: 	etcdClient := l.EtcdClient
103: 	genClient := l.GenericClient
104: 
105: 	tokens := parseFilter(l.Filter)
106: 	if len(tokens) == 0 || (len(tokens) == 1 && tokens[0] == "all") {
107: 		tokens = defaultResourceTokens()
108: 	}
109: 	resourceMappings, err := resolveResourceMappings(genClient.RESTMapper(), tokens)
110: 	if err != nil {
111: 		return err
112: 	}
113: 
114: 	// Identify etcds to operate on
115: 	etcdList, err := cmdutils.GetEtcdList(ctx, etcdClient, l.etcdRefList, l.AllNamespaces, l.GetNamespace(), l.LabelSelector)
116: 	if err != nil {
117: 		return err
118: 	}
119: 	if len(etcdList.Items) == 0 {
120: 		if !l.AllNamespaces {
121: 			return fmt.Errorf("no Etcd resources found in namespace %q", l.GetNamespace())
122: 		}
123: 		out.Info(l.IOStreams.Out, "No Etcd resources found across all namespaces")
124: 		return nil
125: 	}
126: 
127: 	result := Result{
128: 		Etcds: make([]EtcdResourceResult, 0, len(etcdList.Items)),
129: 		Kind:  "EtcdResourceList",
130: 	}
131: 	for _, etcd := range etcdList.Items {
132: 		etcdResult := EtcdResourceResult{
133: 			Etcd:  EtcdRef{Name: etcd.Name, Namespace: etcd.Namespace},
134: 			Items: make([]ResourceListPerKey, 0),
135: 		}
136: 
137: 		labelSelector := fmt.Sprintf("app.kubernetes.io/part-of=%s", etcd.Name)
138: 		for _, mapping := range resourceMappings {
139: 			resourceNamespace := ""
140: 			if mapping.Scope.Name() == meta.RESTScopeNameNamespace {
141: 				resourceNamespace = etcd.Namespace
142: 			}
143: 			resourceList, err := genClient.Dynamic().Resource(mapping.Resource).Namespace(resourceNamespace).List(ctx, metav1.ListOptions{LabelSelector: labelSelector})
144: 			if err != nil {
145: 				out.Warning(l.IOStreams.Out, "Failed to list ", mapping.Resource.Resource, " for etcd ", etcd.Name, ": ", err.Error())
146: 				continue
147: 			}
148: 			if len(resourceList.Items) == 0 {
149: 				continue
150: 			}
151: 			resourceKey := ResourceKey{Group: mapping.Resource.Group, Version: mapping.Resource.Version, Resource: mapping.Resource.Resource, Kind: mapping.GroupVersionKind.Kind}
152: 			for _, item := range resourceList.Items {
153: 				found := false
154: 				for idx, resourceListPerKey := range etcdResult.Items {
155: 					if resourceListPerKey.Key == resourceKey {
156: 						etcdResult.Items[idx].Resources = append(etcdResult.Items[idx].Resources, toResourceRef(&item))
157: 						found = true
158: 						break
159: 					}
160: 				}
161: 				if !found {
162: 					etcdResult.Items = append(etcdResult.Items, ResourceListPerKey{
163: 						Key:       resourceKey,
164: 						Resources: []ResourceRef{toResourceRef(&item)},
165: 					})
166: 				}
167: 			}
168: 		}
169: 		// Sort within each resource kind by namespace/name for determinism
170: 		for kindIdx := range etcdResult.Items {
171: 			sort.Slice(etcdResult.Items[kindIdx].Resources, func(i, j int) bool {
172: 				resourceA, resourceB := etcdResult.Items[kindIdx].Resources[i], etcdResult.Items[kindIdx].Resources[j]
173: 				if resourceA.Namespace == resourceB.Namespace {
174: 					return resourceA.Name < resourceB.Name
175: 				}
176: 				return resourceA.Namespace < resourceB.Namespace
177: 			})
178: 		}
179: 		result.Etcds = append(result.Etcds, etcdResult)
180: 	}
181: 
182: 	// Sort etcds by namespace/name
183: 	sort.Slice(result.Etcds, func(i, j int) bool {
184: 		if result.Etcds[i].Etcd.Namespace == result.Etcds[j].Etcd.Namespace {
185: 			return result.Etcds[i].Etcd.Name < result.Etcds[j].Etcd.Name
186: 		}
187: 		return result.Etcds[i].Etcd.Namespace < result.Etcds[j].Etcd.Namespace
188: 	})
189: 	if l.Printer != nil {
190: 		var outputData []byte
191: 		outputData, err = l.Printer.Print(result)
192: 		if err != nil {
193: 			return fmt.Errorf("failed to marshal result to desired format: %w", err)
194: 		}
195: 		fmt.Fprintf(l.IOStreams.Out, "%s\n", string(outputData))
196: 		return nil
197: 	}
198: 	l.renderListResources(out, result.Etcds)
199: 	return nil
200: }
